PRAGMA foreign_keys=ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE jurisdictions(id TEXT PRIMARY KEY, country TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, kind TEXT, scope TEXT NOT NULL);
CREATE TABLE plates(uid TEXT PRIMARY KEY, jurisdiction_id TEXT NOT NULL REFERENCES jurisdictions(id), name TEXT NOT NULL, category TEXT, record_origin TEXT NOT NULL CHECK(record_origin IN ('lpg_catalog','report_candidate')), issue_start INTEGER, issue_end INTEGER, era_status TEXT NOT NULL DEFAULT 'unknown', identity_status TEXT NOT NULL, visual_status TEXT NOT NULL, catalog_json TEXT NOT NULL);
CREATE TABLE sources(id TEXT PRIMARY KEY, page_url TEXT NOT NULL, authority TEXT, retrieved_at TEXT, archive_path TEXT, archive_sha256 TEXT);
CREATE TABLE assets(sha256 TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), direct_url TEXT, original_path TEXT NOT NULL UNIQUE, width INTEGER, height INTEGER, media_type TEXT, asset_role TEXT NOT NULL, source_label TEXT, creator TEXT, source_license TEXT, license_url TEXT, license_status TEXT NOT NULL, project_use_basis TEXT NOT NULL, retrieved_at TEXT);
CREATE TABLE derivatives(id INTEGER PRIMARY KEY, asset_sha256 TEXT NOT NULL REFERENCES assets(sha256), kind TEXT NOT NULL, path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, transform TEXT NOT NULL, UNIQUE(asset_sha256,kind));
CREATE TABLE plate_assets(plate_uid TEXT NOT NULL REFERENCES plates(uid), asset_sha256 TEXT NOT NULL REFERENCES assets(sha256), match_status TEXT NOT NULL CHECK(match_status IN ('candidate','conflict','verified')), match_basis TEXT NOT NULL, human_review TEXT NOT NULL DEFAULT 'pending', PRIMARY KEY(plate_uid,asset_sha256));
CREATE TABLE claims(id INTEGER PRIMARY KEY, plate_uid TEXT REFERENCES plates(uid), field TEXT NOT NULL, claimed_value TEXT NOT NULL, source_ref TEXT NOT NULL, status TEXT NOT NULL, note TEXT);
CREATE TABLE issues(id INTEGER PRIMARY KEY, plate_uid TEXT REFERENCES plates(uid), asset_sha256 TEXT REFERENCES assets(sha256), kind TEXT NOT NULL, detail TEXT NOT NULL, next_action TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open');
CREATE INDEX plate_jurisdiction ON plates(jurisdiction_id);
CREATE INDEX matching_status ON plate_assets(match_status,human_review);
CREATE VIEW coverage AS SELECT p.uid,p.name,p.jurisdiction_id,p.record_origin,COUNT(pa.asset_sha256) AS candidate_images,SUM(CASE WHEN pa.match_status='verified' AND pa.human_review='approved' THEN 1 ELSE 0 END) AS approved_images FROM plates p LEFT JOIN plate_assets pa ON p.uid=pa.plate_uid GROUP BY p.uid;
CREATE VIEW approved_app_images AS SELECT p.uid,a.sha256,a.original_path,d.path AS thumbnail_path,a.creator,a.source_license,a.license_url,s.page_url FROM plates p JOIN plate_assets pa ON pa.plate_uid=p.uid JOIN assets a ON a.sha256=pa.asset_sha256 JOIN sources s ON s.id=a.source_id LEFT JOIN derivatives d ON d.asset_sha256=a.sha256 AND d.kind='thumbnail' WHERE pa.match_status='verified' AND pa.human_review='approved' AND p.record_origin='lpg_catalog';
